def compute(vars):
    option_count = vars["v1"]
    exercise_price_per_option = vars["v2"]
    total_value_dollars = option_count * exercise_price_per_option
    total_value_millions = total_value_dollars / 1000000

    return {
        "value": total_value_millions,
        "trace": {
            "option_count": option_count,
            "exercise_price_per_option": exercise_price_per_option,
            "total_value_dollars": total_value_dollars,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
